from 写入第二遍 import add
add('13_004',1.5,'16:9，从武士背后斜仰看断烟囱；武士肩背在左下近侧，米灰砖体压满上方。固定机位承接刀路，碎块飞到镜头近侧时让焦点仍留在大块裂口。','武士右手的刀从身侧斩过断烟囱，大块上先出现几道亮细裂缝，裂缝随切击骤然张开；砖块分成数片向两侧翻离，细砂随后向镜头扑来。武士外衣受冲来的气流掀起，头仍对着被切开的中心。','米灰断烟囱及深灰裂缝充满主要视野，块体间隙露出淡冷灰天空。','冷白天空从块体后侧照出明亮外缘，裂缝的亮线为刀击重音，迅即恢复砖石明暗。','硬脆石裂分两层爆开，刀风穿过后接颗粒密集的沙响。',phase='result',node={'烟囱.状态':'被武士斩成多块、遮挡视线','武士.刀':'右手斩后持刀','武士.阶段':'面向碎块中心'},meaning='从武士背后看大砖体斩裂，保持原作观察关系，碎块形成下一格的视野盲区。')
add('14_001',7.5,'16:9，武士正面头肩近景；多块失焦砖石从镜头与他之间擦过，机位固定，焦点在围布上方眼缝，前景间隙不断开合。','武士的眼缝仍朝断烟囱来的位置，第一块碎砖擦过时头没有动；下一块遮住视线，他才把下巴向侧一带，眼睛从两个碎块之间找青。原来松下的肩膀重新抬紧，持刀右肘向肋侧收，句尾判断还没说完，瞳孔便锁住突然变近的画外轮廓。','米灰砖块在近层左右穿过，后方只有冷灰天空和稀薄粉尘；不提前露出青的完整身影。','开阔天空的冷白光被碎砖短暂切成明暗变化，围布下侧保持暗灰。','近层碎砖掠风有轻重差别，砂砾相碰；说话的句尾被逼近的衣风顶住。',japanese=['待て…','石を投げて視界を遮ったとなれば、次の一手は…'],tone='第一句短促察觉，后句推理由从容转为警觉，保留未说完。',phase='reaction',kind='mixed',node={'武士.阶段':'碎块间判断青的后招'},pcard={'opening':'武士仍相信自己掌握来路。','beats':['碎块遮眼才偏头找人','肩抬紧、收肘，判断被近处轮廓打断'],'coupling':'不让观众先于这个警觉看清青的近身。','landing':'已察觉危险，反应尚未完成。'})
add('14_002',3,'16:9，越过武士左侧头肩的近景，青从碎石间出现；武士头部在左前景，青的脸、收在头侧的右拳与前倾肩胸在中景，固定机位略随双方下降。','一块砖石擦离青的脸前，她已贴近武士，圆睁的眼睛直指他的头侧；青把右拳收在头旁，另一只手压在身体前侧，胸腰折出向前的弓形。说完短句，她露齿、肩头抢先向前，右拳从头旁骤然冲出，拳路穿过碎石空隙，镜尾将抵到武士头侧。','近处数块米灰砖石从上方和右侧飞离，空隙后是浅冷灰天空，粉尘尚未淹没两人。','开阔天空冷白漫射，碎石阴影短促擦过青额前。','碎砖擦风突然变稀，青一口短促发力呼气，拳头带出更近更窄的破风。',japanese=['そう。そのとおり。これでも食らえ。'],tone='短句果断，最后一句压重，发力与尾音衔接。',phase='preparation',kind='mixed',node={'青.阶段':'近身拳即将命中','双方.距离':'近身拳距'},pcard={'opening':'青已利用遮挡来到近处，攻击意图毫不遮掩。','beats':['碎石让出圆眼与收拳姿态','说完后肩头先行，右拳骤然冲出'],'coupling':'对武士未完判断直接回应，拳从盲区进入。','landing':'拳即将触及头侧，不能提前写成已经打完。'})
